const errors:Record<string,readonly [string,string]>={fullName:['اكتب اسم العضو من جزئين على الأقل، مع مسافة بين الأجزاء.','Enter the member name in at least two parts, separated by a space.'],phone11:['اكتب رقمًا محليًا من ١١ رقمًا أو رقمًا دوليًا يبدأ بعلامة + ورمز الدولة.','Enter an 11-digit local number or an international number starting with + and a country code.'],cardUsed:['رقم الكارت مستخدم أو محفوظ لعضو آخر؛ اختر رقمًا جديدًا.','This card number is used or reserved for another member; choose a new one.'],barcodeUnavailable:['تعذر حجز الباركود. تحقق من الاتصال ثم اضغط إعادة حجز الباركود.','Could not reserve a barcode. Check the connection and reserve again.'],clubChanged:['تم تغيير النادي. حدّث الصفحة ثم أعد المحاولة.','The club changed. Refresh the page and try again.'],auth:['انتهت جلسة الدخول. سجّل الدخول من جديد.','Your session expired. Sign in again.'],forbidden:['ليس لديك صلاحية تنفيذ هذه العملية في الفرع الحالي.','You do not have permission for this operation in the current branch.'],trialExpired:['انتهت التجربة. تواصل مع مسؤول النادي للتفعيل.','The trial ended. Contact your club administrator to activate.'],invalid:['راجع البيانات ورقم الكارت؛ استخدم الحروف الإنجليزية والأرقام والنقطة والشرطة فقط.','Check the fields and card number; use English letters, digits, a dot or a hyphen only.'],photoPending:['انتظر اكتمال تجهيز الصورة قبل الحفظ.','Wait for the photo to finish processing before saving.'],discount:['راجع الخصم؛ لا يسمح بقيمة سالبة أو أكبر من الاشتراك أو بنسبة تتجاوز ١٠٠٪.','Check the discount; negative amounts, values above the subscription and percentages over 100% are not allowed.']};
function message(e:unknown,t:(a:string,b:string)=>string){const code=e instanceof Error?e.message:'',found=errors[code];return found?t(found[0],found[1]):t('راجع الحقول والاتصال بالخادم؛ لم يتم اعتماد العملية.','Check the fields and server connection; the operation was not accepted.');}
function phoneInput(value:string){const n=normalizeDigits(value).replace(/[^+\d]/g,'').replace(/(?!^)\+/g,'');return n.slice(0,n.startsWith('+')?16:11);}
function money(s:GymState,n:number,isArabic=true){return new Intl.NumberFormat(isArabic?'ar-EG-u-nu-latn':'en-GB',{style:'currency',currency:s.settings.currency}).format(n/100);}
