async function reserve(p:ConsoleProps,member:string,code?:string){const r=await fetch('/api/member-barcode',{method:'POST',headers:{'Content-Type':'application/json','X-GymOS-Tenant':p.owner},body:JSON.stringify({branch:p.branch,member,code}),signal:AbortSignal.timeout(10000)});const d=await r.json();if(!r.ok)throw Error(typeof d.error==='string'?d.error:'barcodeUnavailable');if(typeof d.code!=='string'||!/^[A-Z0-9][A-Z0-9._-]{0,63}$/.test(d.code))throw Error('barcodeUnavailable');return d.code;}
function permission(p:ConsoleProps,type:string){return !p.readOnly&&receptionPermitted(p.role,type,p.state.settings.receptionGrants?.[p.actor]);}
function Photo({member,size=60}:{member:Member;size?:number}){return <MemberAvatar member={member} size={size} className={styles.photo} fallbackClassName={styles.avatar}/>;}
function filterOptions(t:(a:string,b:string)=>string){return [['present',t('الموجودون الآن','Present now')],['active',t('السارية','Active')],['expired',t('المنتهية','Expired')],['warning',t('قرب الانتهاء','Expiring soon')],['debt',t('المديونيات','Debts')],['long',t('أكثر من ٩٠ دقيقة','Over 90 minutes')],['new',t('الأعضاء الجدد','New members')]] as string[][];}
function subscriptionLabel(x:ReturnType<typeof memberSummary>,t:(a:string,b:string)=>string){return x.remaining<0?t('انتهى الاشتراك','Expired'):x.status==='warning'?t('قريب من الانتهاء','Expiring soon'):x.status==='active'?t('اشتراك ساري','Active'):x.issue==='quota'?t('نفدت الحصص','Sessions exhausted'):t('غير مفعل / غير متاح','Inactive / unavailable');}
function SubscriptionBadge({x,t}:{x:ReturnType<typeof memberSummary>;t:(a:string,b:string)=>string}){return <span className={styles[x.status==='expired'&&x.remaining>=0?'neutral':x.status]}>{subscriptionLabel(x,t)}</span>;}
const factLabels:Record<string,string>={'الباقة':'Plan','نهاية الاشتراك':'Subscription end','المدفوع':'Paid','المتبقي':'Outstanding','حالة الحضور':'Attendance status','وقت الدخول':'Check-in time','مدة البقاء':'Duration','العنوان':'Address','الهاتف الإضافي':'Additional phone','تاريخ التسجيل':'Registration date','الميلاد':'Date of birth','النوع':'Gender','بداية الاشتراك':'Subscription start','الأيام المتبقية':'Days remaining','الحصص المسموحة':'Allowed sessions','الحصص المستخدمة':'Sessions used','الحصص المتبقية':'Sessions remaining','آخر تجديد':'Last renewal','آخر حضور':'Last attendance','عدد أيام الحضور':'Attendance days','حالة التواجد':'Presence status','مدة الجلسة الحالية':'Current session duration','إجمالي المدفوعات المعتمدة':'Total approved payments','الملاحظات':'Notes','ملاحظات الاشتراك':'Subscription notes'};function factLabel(k:string,t:(a:string,b:string)=>string){return t(k,factLabels[k]??k);}function displayTime(s:GymState,at:string,isArabic=true){return new Date(at).toLocaleTimeString(isArabic?'ar-EG-u-nu-latn':'en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:s.settings.timezone});}
